package com.aoo.bcg.gamespi.resource;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class RoomResourceRegistryTest{@Test void requiresCompleteInventoryAndReleasesInReverseOrder(){var released=new ArrayList<String>();var registry=new RoomResourceRegistry(7);for(var kind:RoomResourceRegistry.Kind.values()){String id=kind.name();registry.register(new RoomResourceRegistry.OwnedResource(kind,"room-runtime",id,()->released.add(id)));}registry.activate();registry.close();var expected=new ArrayList<String>();for(var kind:RoomResourceRegistry.Kind.values())expected.add(kind.name());Collections.reverse(expected);assertEquals(expected,released);registry.close();assertEquals(expected,released);}@Test void incompleteInventoryCannotActivate(){var registry=new RoomResourceRegistry(8);registry.register(new RoomResourceRegistry.OwnedResource(RoomResourceRegistry.Kind.PLAYERS,"room","players",()->{}));assertThrows(IllegalStateException.class,registry::activate);}}
